@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemsDescription : string
}

class PickupVehicle {
  + LicensePlateNumber : string
  + StorageSpace : int
  + AvailableDays : date[]
}

class VolunteerDriver {
  + FirstName : string
  + LastName : string
  + AvailableDays : date[]
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class SecondHandArticle {
  + RFIDTag : int
  + Description : string
  + Category : string
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

class PickupRoute {
  + RouteNumber : int
  + Days : date[]
}

class DeliveryService {}

abstract class Employee {
  + FirstName : string
  + LastName : string
}

class H2SEmployee {}

PickupVehicle "0..*" -- "*" VolunteerDriver : assignedTo
VolunteerDriver "1" -- "*" PickupRoute : follows
DistributionCenter "0..*" -- "*" SecondHandArticle : receives
FoodBank "0..*" -- "*" SecondHandArticle : receives
SecondHandArticle "1" -- "1" H2SEmployee : examinedBy
H2SEmployee "0..*" -- "*" Client : callsForDelivery
Client "0..*" -- "*" DeliveryService : uses

@enduml

